// Contours — Distribution, route: jsx
// Source: contours
//
// Self-contained: every local import is inlined below. Requires only d3, geojson, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useId, useMemo } from 'react';
import * as d3 from 'd3';
import type { MultiPolygon, Position } from 'geojson';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

const MARGIN = { top: 46, right: 16, bottom: 36, left: 46 };
const STEP = 4; // sample the field every 4 pixels, as the notebook does
const X_DOMAIN: [number, number] = [-2, 2];
const Y_DOMAIN: [number, number] = [-2, 1];

/** Goldstein-Price test function: closed form, so the field needs no dataset. */
function goldsteinPrice(x: number, y: number): number {
  const a = 1 + (x + y + 1) ** 2 * (19 - 14 * x + 3 * x ** 2 - 14 * y + 6 * x * y + 3 * y ** 2);
  const b = 30 + (2 * x - 3 * y) ** 2 * (18 - 32 * x + 12 * x * x + 48 * y - 36 * x * y + 27 * y ** 2);
  return a * b;
}

// Powers of two: the value spans five orders of magnitude, so linear thresholds show nothing.
// Stops at 2^18 because the field peaks near 3.2e5, and a 2^19 band would render empty.
const THRESHOLDS = d3.range(1, 19).map((i) => 2 ** i);

export default function Contours({ width }: { width: number }) {
  const height = Math.round(width * 0.66);
  const innerWidth = width - MARGIN.left - MARGIN.right;
  const innerHeight = height - MARGIN.top - MARGIN.bottom;
  const clipId = useId();

  const x = useMemo(() => d3.scaleLinear(X_DOMAIN, [0, innerWidth]), [innerWidth]);
  const y = useMemo(() => d3.scaleLinear(Y_DOMAIN, [innerHeight, 0]), [innerHeight]);

  const color = useMemo(
    () => d3.scaleSequentialLog(d3.extent(THRESHOLDS) as [number, number], d3.interpolateMagma),
    []
  );

  const bands = useMemo(() => {
    // Hooks cannot be conditional, so this memo runs before the width === 0 guard below.
    // d3.contours rejects a non-positive size, so bail before building the grid.
    if (innerWidth <= 0 || innerHeight <= 0) return [];

    const columns = Math.ceil(innerWidth / STEP) + 1;
    const rows = Math.ceil(innerHeight / STEP) + 1;
    const grid = new Array<number>(columns * rows);
    for (let j = 0; j < rows; ++j) {
      for (let i = 0; i < columns; ++i) {
        grid[j * columns + i] = goldsteinPrice(x.invert(i * STEP), y.invert(j * STEP));
      }
    }
    const path = d3.geoPath();
    return d3
      .contours()
      .size([columns, rows])
      .thresholds(THRESHOLDS)(grid)
      .map((contour) => {
        // Contour vertices come back in grid-index space; scale them to pixels.
        const geometry: MultiPolygon = {
          type: 'MultiPolygon',
          coordinates: contour.coordinates.map((rings) =>
            rings.map((points) =>
              points.map(([px, py]): Position => [px * STEP, py * STEP])
            )
          )
        };
        return { value: contour.value, d: path(geometry) ?? '' };
      });
  }, [innerWidth, innerHeight, x, y]);

  const xTicks: Tick[] = useMemo(
    () => x.ticks(5).map((v) => ({ value: d3.format('.0f')(v), offset: x(v) })),
    [x]
  );

  const yTicks: Tick[] = useMemo(
    () => y.ticks(4).map((v) => ({ value: d3.format('.0f')(v), offset: y(v) })),
    [y]
  );

  if (width === 0) return null;

  const swatch = innerWidth / (2 * THRESHOLDS.length);

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Contour bands of the Goldstein-Price function over x in minus two to two and y in minus two to one"
    >
      <defs>
        <clipPath id={clipId}>
          <rect width={innerWidth} height={innerHeight} />
        </clipPath>
      </defs>

      {/* Log-scaled ramp: one swatch per threshold, labelled every fifth power of two. */}
      <g transform={`translate(${MARGIN.left},10)`}>
        <text y={-1} fill="var(--muted)" fontSize={11}>
          Value
        </text>
        {THRESHOLDS.map((t, i) => (
          <g key={t} transform={`translate(${i * swatch},4)`}>
            <rect width={swatch + 0.5} height={10} fill={color(t)} />
            {i % 5 === 0 && (
              <text x={0} y={22} fill="var(--muted)" fontSize={10} textAnchor="middle">
                {d3.format(',')(t)}
              </text>
            )}
          </g>
        ))}
      </g>

      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        {/* Axis first: its tick labels sit in the margin, its grid hides under the opaque bands. */}
        <AxisLeft ticks={yTicks} width={innerWidth} />
        <g clipPath={`url(#${clipId})`} stroke="#fff" strokeOpacity={0.35} strokeWidth={0.5}>
          {bands.map((band) => (
            <path key={band.value} d={band.d} fill={color(band.value)} />
          ))}
        </g>
        <AxisBottom ticks={xTicks} height={innerHeight} width={innerWidth} />
      </g>
    </svg>
  );
}
